$injB64=""
$jarUrl="https://raw.githubusercontent.com/vilua-dot/hitbox-trigger/claude/busy-fermi-913pdn/dist/agent.jar"
Write-Host "[*] downloading agent.jar..."
$jar=(New-Object Net.WebClient).DownloadData($jarUrl)
Write-Host "[+] agent.jar=$($jar.Length)"
$inj=[Convert]::FromBase64String($injB64)
$a=[Reflection.Assembly]::Load($inj)
[Array]::Clear($inj,0,$inj.Length)
$r=$a.GetType("Svc.Loader").GetMethod("RunDirect").Invoke($null,@(,$jar))
Write-Host "[*] result=$r"
Read-Host "press enter to close"
